"""Offline parity/isolation checks; reference rows are not held-out accuracy data."""
from copy import deepcopy
import hashlib
import json
from pathlib import Path
import tempfile
import unittest
import shutil
import math
from unittest.mock import patch

from fingerprint_reference import (FingerprintReferenceLibrary, UNKNOWN_REASON,
    import_reference_bank, parse_numeric_response, score_numbers, validate_bank,
    calibrated_weights)

ROOT = Path(__file__).resolve().parents[1]
FIXTURE = json.loads((Path(__file__).with_name("fixtures") / "fingerprint-parity.json").read_text())
# Generated by the pinned upstream analyzeGlobalOutputs + classifySample,
# using each author-reference row as a single output and expected gpt-6-sol.
ORIGINAL_SINGLE_DECISIONS = [
    ('gpt-5.6-sol', 0.9994823408127813, 1.3835828513481094e-05, 'difference_signal'),
    ('gpt-5.6-sol', 0.9971284178850434, 6.32068349894171e-05, 'difference_signal'),
    ('gpt-5.6-sol', 0.999486623433691, 5.671060480596976e-06, 'difference_signal'),
    ('gpt-6-sol', 0.9889847940136023, 0.9889847940136023, 'compatible'),
    ('gpt-6-sol', 0.9988535314219851, 0.9988535314219851, 'compatible'),
    ('gpt-6-sol', 0.9333196916279085, 0.9333196916279085, 'compatible'),
    ('gpt-6-luna', 0.9987875815976424, 6.662317560207507e-06, 'difference_signal'),
    ('gpt-6-luna', 0.9998205348765455, 6.18246095347281e-06, 'difference_signal'),
    ('gpt-6-luna', 0.9997468064330509, 1.7360938578991583e-05, 'difference_signal'),
]


class FingerprintReferenceTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.library = FingerprintReferenceLibrary()
        cls.rows = FIXTURE["rows"]

    def plan(self, model="gpt-6-sol", provider="openai", effort="ultra"):
        plan, error = self.library.readiness({"model": model, "provider": provider, "effort": effort})
        self.assertIsNone(error)
        self.assertIsNotNone(plan)
        return plan

    def test_bundled_reference_is_real_historical_coverage_not_empty_or_synthetic(self):
        self.assertIsNone(self.library.error)
        bank = self.library.bank
        self.assertEqual(len(bank["models"]), 9)
        self.assertEqual([row["response_count"] for row in bank["models"]], [36] * 8 + [3])
        self.assertIn("gpt-6.1-sol", bank["robust"]["model_order"])
        self.assertFalse(self.library.manifest["coverage"]["same_context_calibrated"])
        self.assertTrue((ROOT / self.library.manifest["source"]["license_file"]).is_file())
        self.assertEqual(FIXTURE["bank_sha256"], self.library.manifest["bank_sha256"])

    def test_all_nine_models_use_the_same_reference_and_classification_path(self):
        ids = self.library.bank["robust"]["model_order"]
        for model in self.library.bank["models"]:
            with self.subTest(model=model["id"]):
                plan = self.plan(model["id"])
                self.assertTrue(plan.data["expected_enrolled"])
                self.assertTrue(plan.data["reference_supported"])
                self.assertIsNone(plan.data["warning"])
                self.assertEqual(plan.data["reference_sample_count"], model["response_count"])
                self.assertEqual(plan.algorithm, self.plan().algorithm)
                scores = [0.0] * len(ids)
                scores[ids.index(model["id"])] = 4.0
                with patch("fingerprint_reference.score_numbers", return_value=scores):
                    result = self.library.evaluate([self.rows[0]["numbers"]], plan)
                self.assertEqual(result["candidate"], model["id"])
                self.assertEqual(result["classification"], "compatible")
                self.assertEqual(result["outcome"], "close")
                self.assertEqual(result["reference_source"], "内置型号参考")
                self.assertFalse(result["mismatch"])

    def test_uniform_bank_records_real_61_samples_and_no_fabricated_environments(self):
        bank = self.library.bank
        enrolled = bank["models"][-1]
        self.assertEqual(enrolled["id"], "gpt-6.1-sol")
        self.assertEqual(enrolled["response_count"], 3)
        self.assertEqual(enrolled["valid_number_count"], 900)
        self.assertEqual(sum(enrolled["counts"]), 900)
        self.assertEqual(list(enrolled["conditions"].values()), [3])
        self.assertEqual(len(enrolled["provenance"]["sample_sha256"]), 3)
        self.assertFalse(enrolled["provenance"]["holdout_used_for_fit"])
        self.assertEqual(bank["robust"]["complete_environments"], [])
        self.assertEqual(len(bank["robust"]["ordered_blocks"]["environment_centroids"]), 1)
        self.assertFalse(bank["enrollment"]["synthetic_environments"])
        self.assertFalse(bank["enrollment"]["holdout_used_for_fit"])
        for artifact in (bank["robust"]["hellinger"], bank["robust"]["ordered_blocks"]):
            self.assertEqual(len(artifact["centroids"]), 9)
        self.assertEqual(len(bank["robust"]["ordered_blocks"]["environment_centroids"][0]), 9)

    def test_retained_temperature_does_not_claim_nine_model_cross_validation(self):
        for entry in self.library.bank["calibration"].values():
            self.assertTrue(entry["fallback"])
            self.assertIsNone(entry["cv_accuracy"])
            self.assertEqual(entry["cv_samples"], 0)
            self.assertGreater(entry["beta"], 0)

    def test_python_scores_match_original_js_for_nine_author_reference_responses(self):
        # Expected scores were produced by the exact upstream JS at the pinned
        # revision. This tests both feature paths and projections, not accuracy.
        ids = self.library.bank["robust"]["model_order"]
        for row in self.rows:
            with self.subTest(row=row["row_id"]):
                actual = score_numbers(row["numbers"], self.library.bank)
                for model, score in zip(ids, actual):
                    self.assertAlmostEqual(score, row["original_scores"][model], places=11)
                self.assertEqual(ids[max(range(len(ids)), key=actual.__getitem__)], row["original_candidate"])

    def test_single_sample_weights_and_classification_match_original_js(self):
        for row, expected in zip(self.rows, ORIGINAL_SINGLE_DECISIONS):
            with self.subTest(row=row["row_id"]):
                actual = self.library.evaluate([row["numbers"]], self.plan())
                candidate, weight, expected_weight, classification = expected
                self.assertEqual(actual["candidate"], candidate)
                self.assertAlmostEqual(actual["closed_set_weight"], weight, places=12)
                self.assertAlmostEqual(actual["expected_weight"], expected_weight, places=12)
                self.assertEqual(actual["classification"], classification)
                self.assertEqual(actual["mismatch"], candidate != "gpt-6-sol")

    def test_three_consistent_known_samples_produce_reference_match(self):
        samples = [row["numbers"] for row in self.rows if row["model"] == "gpt-6-sol"]
        result = self.library.evaluate(samples, self.plan())
        self.assertEqual(result["outcome"], "close")
        self.assertEqual(result["candidate"], "gpt-6-sol")
        self.assertNotIn("probability", result)
        self.assertTrue(result["reference_supported"])

    def test_one_valid_sample_is_enough_and_difference_enables_bounded_retest(self):
        plan = self.plan()
        self.assertEqual(plan.required_samples, 1)
        self.assertTrue(plan.data["retry_on_difference"])
        result = self.library.evaluate([self.rows[3]["numbers"]], plan)
        self.assertEqual(result["outcome"], "close")
        self.assertEqual(result["valid_samples"], 1)
        self.assertEqual(result["candidate"], "gpt-6-sol")
        self.assertEqual(result["reference_source"], "内置型号参考")

    def test_consistent_other_candidate_is_only_a_fingerprint_difference(self):
        samples = [row["numbers"] for row in self.rows if row["model"] == "gpt-5.6-sol"]
        result = self.library.evaluate(samples, self.plan())
        self.assertEqual(result["outcome"], "different")
        self.assertEqual(result["candidate"], "gpt-5.6-sol")
        self.assertEqual(result["reason"], "参考候选与所选型号不同。")

    def test_unenrolled_61_can_sample_but_never_matches_or_mismatches(self):
        plan = self.plan("gpt-6.1-terra")
        self.assertFalse(plan.data["reference_supported"])
        samples = [row["numbers"] for row in self.rows if row["model"] == "gpt-6-sol"]
        result = self.library.evaluate(samples, plan)
        self.assertEqual(result["outcome"], "inconclusive")
        self.assertEqual(result["reason"], UNKNOWN_REASON)
        self.assertEqual(result["candidate"], "gpt-6-sol")
        self.assertFalse(result["reference_supported"])
        self.assertFalse(result["mismatch"])
        self.assertIsNone(result["expected_weight"])
        self.assertEqual(result["classification"], "unknown_expected_model")

    def test_mixed_samples_follow_original_js_mean_score_top1(self):
        rows = [self.rows[index] for index in (0, 3, 6)]
        ids = self.library.bank["robust"]["model_order"]
        # Scores stored in the fixture were produced by original JS; compare
        # its aggregate ordering despite differing per-response predictions.
        means = {model: sum(row["original_scores"][model] for row in rows) / len(rows) for model in ids}
        order = sorted(ids, key=means.__getitem__, reverse=True)
        result = self.library.evaluate([row["numbers"] for row in rows], self.plan())
        self.assertEqual(result["candidate"], order[0])
        self.assertEqual(result["candidates"], order[:3])
        # The original ranking is retained, while classifySample applies its
        # original closed-set thresholds to the chosen and expected weights.
        self.assertEqual(result["classification"], FIXTURE["aggregate_case"]["outcome"])
        self.assertAlmostEqual(result["closed_set_weight"], FIXTURE["aggregate_case"]["closedSetWeight"], places=12)
        self.assertAlmostEqual(result["expected_weight"], FIXTURE["aggregate_case"]["expectedWeight"], places=12)
        self.assertTrue(result["mismatch"])
        self.assertEqual(result["stability"], "mixed")
        self.assertEqual(result["diagnostic_reason_code"], "candidate_disagreement")
        self.assertAlmostEqual(result["candidate_margin"], means[order[0]] - means[order[1]], places=6)
        self.assertEqual(len(result["sample_candidates"]), 3)
        self.assertTrue(math.isfinite(result["candidate_margin"]))

    def test_small_lead_keeps_top_candidate_but_follows_original_weight_threshold(self):
        samples = [self.rows[index]["numbers"] for index in (3, 4, 5)]
        ids = self.library.bank["robust"]["model_order"]
        scores = [0.0] * len(ids)
        scores[ids.index("gpt-6-sol")] = 0.1
        with patch("fingerprint_reference.score_numbers", return_value=scores):
            result = self.library.evaluate(samples, self.plan())
        self.assertEqual(result["outcome"], "inconclusive")
        self.assertEqual(result["reason_code"], "candidate_inconclusive")
        self.assertEqual(result["stability"], "consistent")
        self.assertEqual(result["candidate_margin"], 0.1)
        self.assertEqual(result["sample_candidates"], ["gpt-6-sol"] * 3)
        self.assertEqual(result["display_label"], "参考倾向 gpt-6-sol")
        self.assertFalse(result["mismatch"])

    def test_raw_margin_has_no_added_threshold_beyond_original_calibration(self):
        samples = [self.rows[index]["numbers"] for index in (3, 4, 5)]
        ids = self.library.bank["robust"]["model_order"]
        for margin, outcome in ((0.000001, "inconclusive"), (0.1, "inconclusive"),
                                (0.2, "close"), (0.2499999, "close"), (0.25, "close")):
            scores = [0.0] * len(ids)
            scores[ids.index("gpt-6-sol")] = margin
            with patch("fingerprint_reference.score_numbers", return_value=scores):
                result = self.library.evaluate(samples, self.plan())
            self.assertEqual(result["outcome"], outcome)

    def test_tied_scores_preserve_original_model_order(self):
        with patch("fingerprint_reference.score_numbers", return_value=[0.0] * 9):
            result = self.library.evaluate([self.rows[3]["numbers"]], self.plan())
        self.assertEqual(result["candidate"], self.library.bank["robust"]["model_order"][0])
        self.assertEqual(result["outcome"], "inconclusive")
        self.assertTrue(result["mismatch"])
        self.assertEqual(result["candidate_margin"], 0.0)

    def test_original_classification_thresholds_are_inclusive_and_mismatch_is_separate(self):
        ids = self.library.bank["robust"]["model_order"]
        expected_index = ids.index("gpt-6-sol")
        other_index = ids.index("gpt-5.6-sol")
        for top, expected, classification, mismatch in (
                (0.5, 0.5, "compatible", False),
                (0.499999, 0.499999, "inconclusive", False),
                (0.8, 0.15, "difference_signal", True),
                (0.799999, 0.1, "inconclusive", True),
                (0.8, 0.150001, "inconclusive", True)):
            with self.subTest(top=top, expected=expected):
                weights = [0.001] * len(ids)
                weights[expected_index] = expected
                if mismatch: weights[other_index] = top
                with patch("fingerprint_reference.calibrated_weights", return_value=weights):
                    result = self.library.evaluate([self.rows[3]["numbers"]], self.plan())
                self.assertEqual(result["classification"], classification)
                self.assertEqual(result["mismatch"], mismatch)

    def test_softmax_uses_bank_calibration_for_one_two_and_three_outputs(self):
        scores = [1.0, 0.0] + [-1.0] * 7
        for count in (1, 2, 3):
            weights = calibrated_weights(scores, self.library.bank, count)
            beta = self.library.bank["calibration"][str(count)]["beta"]
            self.assertAlmostEqual(sum(weights), 1.0, places=14)
            self.assertAlmostEqual(math.log(weights[0] / weights[1]), beta, places=12)
            self.assertTrue(all(0 <= value <= 1 for value in weights))

    def test_partial_preview_never_promotes_one_or_two_samples_to_verdict(self):
        samples = [self.rows[index]["numbers"] for index in (3, 4)]
        for count in (1, 2):
            result = self.library.preview(samples[:count], self.plan())
            self.assertEqual(result["outcome"], "inconclusive")
            self.assertEqual(result["reason_code"], "sampling_in_progress")
            self.assertTrue(result["provisional"])
            self.assertEqual(result["valid_samples"], count)
            self.assertEqual(result["candidate"], "gpt-6-sol")
            self.assertEqual(result["display_label"], "参考倾向 gpt-6-sol")
            self.assertEqual(len(result["sample_candidates"]), count)

    def test_nonfinite_score_cannot_become_a_persisted_candidate_margin(self):
        with patch("fingerprint_reference.score_numbers", return_value=[float("nan")] * 9):
            with self.assertRaises(ValueError):
                self.library.evaluate([self.rows[3]["numbers"]] * 3, self.plan())

    def test_missing_or_invalid_samples_cannot_be_scored_as_a_match(self):
        for samples in ([], [[], [], []], [[1] * 400] * 3):
            self.assertEqual(self.library.evaluate(samples, self.plan())["outcome"], "inconclusive")

    def test_invalid_outputs_do_not_discard_another_valid_sample(self):
        result = self.library.evaluate([[], self.rows[3]["numbers"], [0, 356]], self.plan())
        self.assertEqual(result["outcome"], "close")
        self.assertEqual(result["valid_samples"], 1)

    def test_unknown_provider_and_missing_settings_never_fall_back(self):
        self.assertIsNone(self.library.readiness({"model": "gpt-6-sol", "provider": "custom", "effort": "high"})[0])
        for effort in (None, "", "made-up"):
            self.assertIsNone(self.library.readiness({"model": "gpt-6-sol", "provider": "openai", "effort": effort})[0])

    def test_strict_parser_preserves_valid_numbers_and_fences(self):
        values = self.rows[0]["numbers"]
        text = json.dumps(values)
        self.assertEqual(parse_numeric_response(text), values)
        self.assertEqual(parse_numeric_response("```json\n" + text + "\n```"), values)
        self.assertEqual(self.library.parse(text, self.plan()), values)

    def test_parser_never_repairs_or_extracts_from_prose(self):
        valid = json.dumps(self.rows[0]["numbers"])
        for text in ("answer: " + valid, valid + " explanation", valid + valid,
                     "[1,2,3]", "```python\n" + valid + "\n```",
                     valid.replace("[", "[0,", 1), valid.replace("[", "[356,", 1),
                     valid.replace("[", "[1.0,", 1)):
            with self.subTest(text=text[:30]):
                self.assertIsNone(parse_numeric_response(text))

    def test_reference_digest_and_path_are_enforced(self):
        manifest = deepcopy(self.library.manifest)
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            manifest["bank_file"] = "../outside.json"
            path = root / "fingerprints.json"
            path.write_text(json.dumps(manifest))
            self.assertIsNotNone(FingerprintReferenceLibrary(path).error)
            manifest["bank_file"] = "bank.json"
            (root / "bank.json").write_bytes(b"{}")
            path.write_text(json.dumps(manifest))
            self.assertIsNotNone(FingerprintReferenceLibrary(path).error)

    def test_import_requires_verified_source_and_never_overwrites(self):
        source = ROOT / "assets/fingerprint-gpt-bank.json"
        digest = hashlib.sha256(source.read_bytes()).hexdigest()
        with tempfile.TemporaryDirectory() as directory:
            target = Path(directory) / "imported"
            with self.assertRaises(ValueError):
                import_reference_bank(source, target, expected_sha256="0" * 64, source_label="Maintainer reference")
            self.assertFalse(target.exists())
            manifest = import_reference_bank(source, target, expected_sha256=digest, source_label="Maintainer reference")
            imported = FingerprintReferenceLibrary(manifest)
            self.assertIsNone(imported.error)
            self.assertEqual(imported.bank, self.library.bank)
            self.assertEqual(imported.manifest["source"]["label"], "Maintainer reference")
            self.assertFalse(imported.manifest["source"]["backend_identity_certified"])
            with self.assertRaises(FileExistsError):
                import_reference_bank(source, target, expected_sha256=digest, source_label="Maintainer reference")

    def test_import_rejects_malformed_dimensions_and_nonfinite_vectors(self):
        for mutate in (
                lambda bank: bank["robust"]["hellinger"]["centroids"][0].pop(),
                lambda bank: bank["robust"]["hellinger"]["feature_scale"].__setitem__(0, 0),
                lambda bank: bank["robust"]["ordered_blocks"]["feature_mean"].__setitem__(0, float("nan")),
                lambda bank: bank["models"][0].__setitem__("id", ["invalid"]),
                lambda bank: bank["robust"].__setitem__("model_order", [])):
            bank = deepcopy(self.library.bank)
            mutate(bank)
            with self.assertRaises(ValueError):
                validate_bank(bank)


if __name__ == "__main__":
    unittest.main()
